"use strict";

var _EnterpriseCustomFilter = require("../EnterpriseCustomFilter.utils");
describe('EnterpriseCustomFilter.utils', function () {
  describe('enterpriseCustomFilterQuery', function () {
    test('should match snapshot', function () {
      expect((0, _EnterpriseCustomFilter.enterpriseCustomFilterQuery)(1)).toMatchSnapshot();
    });
  });
  describe('enterpriseFilterNamesQuery', function () {
    test('should match snapshot', function () {
      expect(_EnterpriseCustomFilter.enterpriseFilterNamesQuery).toMatchSnapshot();
    });
  });
  describe('convertResultsToFilterOptions', function () {
    test('should default', function () {
      expect((0, _EnterpriseCustomFilter.convertResultsToFilterOptions)()).toEqual([]);
      expect((0, _EnterpriseCustomFilter.convertResultsToFilterOptions)(null)).toEqual([]);
      expect((0, _EnterpriseCustomFilter.convertResultsToFilterOptions)([])).toEqual([]);
    });
    test('should return options', function () {
      expect((0, _EnterpriseCustomFilter.convertResultsToFilterOptions)([{
        name: 'Jan Levinson'
      }])).toEqual([{
        id: 'Jan Levinson',
        label: 'Jan Levinson'
      }]);
    });
  });
  describe('prependFilterName', function () {
    it('should prepend', function () {
      var callback = jest.fn();
      (0, _EnterpriseCustomFilter.prependFilterName)(callback)('test');
      expect(callback.mock.calls[0][0]).toEqual('customFilter0');
      expect(callback.mock.calls[0][3]).toEqual('test');
    });
  });
});